	int length = str.length();
	int offset = 0;
	while (offset < length) {
		char ch = str.charAt(offset++);
		if (lb.remaining() == 0) {
			lb.expand();
		}
		int byteCount = UTF8.encode(ch, lb.tail());
		lb.written(ch);
		if (byteCount <= 0) {
			throw new IllegalArgumentException("Invalid UTF8 character: " + ch);
		}
	}
	return lb;
}

